let result: TraverserResult<()> = graph.transaction(|g| { g.traversal_mut().add_v("person").property("name", "ann").to_list()?; // A failing traversal is a savepoint: only its own changes are rolled back, and the // closure gets the error and decides (here: go on). let failed = g.traversal_mut().v("1").property("age", 30).constant("x") .as_number(GType::LONG).to_list(); assert!(failed.is_err()); g.traversal_mut().v("2").property("age", 28).to_list()?; Ok(())
