use graphersal::changes::{CommitHook, HookError, RollbackReason}; /// A write-ahead log: one JSON line per committed unit (needs the `serde` feature).
struct Wal<W: std::io::Write + Send + Sync> { out: W, // a `std::fs::File` in a server (call `sync_data()` after the write)
} impl<W: std::io::Write + Send + Sync> CommitHook for Wal<W> { fn name(&self) -> &str { "wal" } fn before_commit(&mut self, changes: &ChangeSet) -> Result<(), HookError> { // Persist BEFORE the commit is final: an Err rolls the unit back and the caller // gets GraphError::CommitRejected { hook: "wal", source }. serde_json::to_writer(&mut self.out, changes)?; self.out.write_all(b"\n")?; self.out.flush()?; Ok(()) } fn after_rollback(&mut self, reason: &RollbackReason) { let _ = reason; // metrics, audit of failed attempts }
} let mut graph = TraversalGraph::tinkerpop_modern();
